SELECT r.*,
         c.customer_nickname as customer_nickname,
         c.customer_avatar as customer_avatar,
         a.agent_name as agent_name,
         a.agent_avatar as agent_avatar,
         h.house_title as house_title
  FROM h_review r
  LEFT JOIN sys_customer c ON r.customer_id = c.customer_id
  LEFT JOIN sys_agent a ON r.agent_id= a.agent_id
  LEFT JOIN h_house h ON r.house_id = h.house_id


